PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?property (COUNT(*) AS ?count)
FROM <http://eobs/gridded>
WHERE {
  ?obs a sosa:Observation ;
       sosa:observedProperty ?property .
}
GROUP BY ?property
ORDER BY DESC(?count)
LIMIT 50

PREFIX sosa: <http://www.w3.org/ns/sosa/>
